import { SlideCommit } from "solen-design/react";

<SlideCommit
  label="Slide to pay"
  doneLabel="Paid"
  errorLabel="Payment failed"
  width={280}
  height={56}
  radius={28}
  speed={50}
  returnBounce={0.38}
  landingDip={0.026}
  holdMs={1500}
  onConfirm={() => new Promise((resolve) => setTimeout(resolve, 1200))}
  onDone={() => console.log("done")}
  onError={(reason) => console.log(reason)}
/>
